-- Keep the already-correct Neptulon40792/group12 row; remove its exact
-- misdecoded duplicate. All other columns, voice and timing are identical.
START TRANSACTION;
SET @neptulon_safe=((SELECT COUNT(*) IN(1,2) AND SUM(SHA2(CONCAT_WS('|',COALESCE(HEX(CAST(g.`CreatureID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`GroupID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`ID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Text` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Type` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Language` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Probability` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Emote` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Duration` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Sound` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`BroadcastTextID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`MinTimer` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`MaxTimer` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`SpellID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`comment` AS CHAR CHARACTER SET utf8mb4)),'NULL')),256)='141f4874124976bd8bab9453362437a68ac72b89fdb6c183fbf2a92a7e5f5ee8')=1 AND SUM(SHA2(CONCAT_WS('|',COALESCE(HEX(CAST(g.`CreatureID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`GroupID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`ID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Text` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Type` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Language` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Probability` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Emote` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Duration` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Sound` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`BroadcastTextID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`MinTimer` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`MaxTimer` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`SpellID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`comment` AS CHAR CHARACTER SET utf8mb4)),'NULL')),256) NOT IN('141f4874124976bd8bab9453362437a68ac72b89fdb6c183fbf2a92a7e5f5ee8','d7994f96631669c3f653fee3240919356db64027702f338e12ecf3dc91cf8100'))=0 FROM creature_text g WHERE g.CreatureID=40792 AND g.GroupID=12));
SET @neptulon_guard=IF(COALESCE(@neptulon_safe,0),'DO 0','SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''Neptulon duplicate group differs; review before updating''');PREPARE neptulon_guard FROM @neptulon_guard;EXECUTE neptulon_guard;DEALLOCATE PREPARE neptulon_guard;
DELETE g FROM creature_text g WHERE @neptulon_safe AND g.CreatureID=40792 AND g.GroupID=12 AND SHA2(CONCAT_WS('|',COALESCE(HEX(CAST(g.`CreatureID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`GroupID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`ID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Text` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Type` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Language` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Probability` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Emote` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Duration` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`Sound` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`BroadcastTextID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`MinTimer` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`MaxTimer` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`SpellID` AS CHAR CHARACTER SET utf8mb4)),'NULL'),COALESCE(HEX(CAST(g.`comment` AS CHAR CHARACTER SET utf8mb4)),'NULL')),256)='d7994f96631669c3f653fee3240919356db64027702f338e12ecf3dc91cf8100';
